//! 本地信標測距定位（不靠地球、不靠 GPS）。
//!
//! 1. 視距（line of sight）：在 DEM 上沿「信標天線 → 太空人天線」的直線取樣（ray marching），
//!    任一點地形高於直線就算被遮擋；超過信標最大距離也算不可見。
//! 2. 覆蓋圖：每格可見信標數。
//! 3. 多邊定位（multilateration）：≥ 3 個可見信標時，用 Gauss–Newton 加權最小平方法解位置，
//!    不確定度由幾何（DOP，(JᵀWJ)⁻¹）與殘差（卡方比）估計。
//! 4. 信標不足時改用航位推算（dead reckoning），不確定度隨距離成長。
//!
//! `simulate` 會用 DEM 產生**模擬**測距（真實距離 + 高斯雜訊），API 回應中會標示 simulated。

use crate::grid::Grid;
use crate::par;
use crate::params::{BeaconSpec, NavParams};
use crate::world::{Beacon, BeaconKind};
use serde::{Deserialize, Serialize};

/// DEM 高度（雙線性內插，以格子中心為取樣點；超出邊界夾到邊緣）。
pub fn terrain_z(dem: &Grid<f32>, x: f32, y: f32) -> f32 {
    let fi = (x / dem.cell_m - 0.5).clamp(0.0, (dem.w - 1) as f32);
    let fj = (y / dem.cell_m - 0.5).clamp(0.0, (dem.h - 1) as f32);
    let (i0, j0) = (fi.floor() as usize, fj.floor() as usize);
    let (i1, j1) = ((i0 + 1).min(dem.w - 1), (j0 + 1).min(dem.h - 1));
    let (tx, ty) = (fi - i0 as f32, fj - j0 as f32);
    let a = dem.get(i0, j0) * (1.0 - tx) + dem.get(i1, j0) * tx;
    let b = dem.get(i0, j1) * (1.0 - tx) + dem.get(i1, j1) * tx;
    a * (1.0 - ty) + b * ty
}

/// 兩個 3D 點之間是否有視線（地形不遮擋）。取樣間距 = 半格。
pub fn line_of_sight(dem: &Grid<f32>, a: [f32; 3], b: [f32; 3]) -> bool {
    let d2 = ((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2)).sqrt();
    let n = (d2 / (0.5 * dem.cell_m)).ceil() as usize;
    for k in 1..n {
        let t = k as f32 / n as f32;
        let (x, y) = (a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t);
        let z_line = a[2] + (b[2] - a[2]) * t;
        if terrain_z(dem, x, y) > z_line {
            return false;
        }
    }
    true
}

pub fn spec(nav: &NavParams, kind: BeaconKind) -> BeaconSpec {
    match kind {
        BeaconKind::Lora => nav.lora,
        BeaconKind::Uwb => nav.uwb,
    }
}

/// 信標天線的 3D 位置。
pub fn beacon_pos(dem: &Grid<f32>, b: &Beacon, nav: &NavParams) -> [f32; 3] {
    [b.x, b.y, terrain_z(dem, b.x, b.y) + nav.beacon_antenna_m]
}

/// 太空人在 (x, y) 時天線的 3D 位置。
pub fn suit_pos(dem: &Grid<f32>, x: f32, y: f32, nav: &NavParams) -> [f32; 3] {
    [x, y, terrain_z(dem, x, y) + nav.suit_antenna_m]
}

#[inline]
fn dist3(a: [f32; 3], b: [f32; 3]) -> f32 {
    ((a[0] - b[0]).powi(2) + (a[1] - b[1]).powi(2) + (a[2] - b[2]).powi(2)).sqrt()
}

/// 信標在位置 (x, y) 是否可用：距離在範圍內且有視線。可用時回傳真實 3D 距離。
pub fn visible_range(dem: &Grid<f32>, b: &Beacon, nav: &NavParams, x: f32, y: f32) -> Option<f32> {
    let horiz = ((b.x - x).powi(2) + (b.y - y).powi(2)).sqrt();
    if horiz > spec(nav, b.kind).max_range_m {
        return None;
    }
    let (bp, sp) = (beacon_pos(dem, b, nav), suit_pos(dem, x, y, nav));
    line_of_sight(dem, bp, sp).then(|| dist3(bp, sp))
}

/// 覆蓋圖：每格可見信標數（以 `stride` 格為一區塊計算，區塊內共用一個值）。
pub fn coverage(dem: &Grid<f32>, beacons: &[Beacon], nav: &NavParams, stride: usize) -> Grid<f32> {
    let stride = stride.max(1);
    let (cw, ch) = (dem.w.div_ceil(stride), dem.h.div_ceil(stride));
    let coarse = par::map_range(cw * ch, |k| {
        let (ci, cj) = (k % cw, k / cw);
        let i = (ci * stride + stride / 2).min(dem.w - 1);
        let j = (cj * stride + stride / 2).min(dem.h - 1);
        let (x, y) = dem.center(i, j);
        beacons
            .iter()
            .filter(|b| visible_range(dem, b, nav, x, y).is_some())
            .count() as f32
    });
    let mut out = Grid::new(dem.w, dem.h, dem.cell_m, 0.0f32);
    for j in 0..dem.h {
        for i in 0..dem.w {
            out.set(i, j, coarse[(j / stride) * cw + i / stride]);
        }
    }
    out
}

/// 一筆測距量測。
#[derive(Clone, Copy, Debug)]
pub struct RangeMeas {
    pub beacon: [f32; 3],
    pub range_m: f32,
    pub sigma_m: f32,
}

/// Gauss–Newton 加權最小平方多邊定位，解 (x, y)；z 取地形 + 天線高。
/// 回傳 (x, y, sigma_m)。少於 3 筆量測或幾何退化時回傳 None。
pub fn multilaterate(
    dem: &Grid<f32>,
    meas: &[RangeMeas],
    init: (f32, f32),
    suit_h: f32,
) -> Option<(f32, f32, f32)> {
    if meas.len() < 3 {
        return None;
    }
    let (mut x, mut y) = (init.0 as f64, init.1 as f64);
    let mut cov = [[0.0f64; 2]; 2];
    let mut chi2 = 0.0f64;
    for _ in 0..20 {
        let z = (terrain_z(dem, x as f32, y as f32) + suit_h) as f64;
        // 正規方程式 (JᵀWJ) Δ = JᵀW r
        let (mut a00, mut a01, mut a11, mut b0, mut b1) = (0.0f64, 0.0, 0.0, 0.0, 0.0);
        chi2 = 0.0;
        for m in meas {
            let (dx, dy, dz) = (
                x - m.beacon[0] as f64,
                y - m.beacon[1] as f64,
                z - m.beacon[2] as f64,
            );
            let pred = (dx * dx + dy * dy + dz * dz).sqrt().max(1e-6);
            let (jx, jy) = (dx / pred, dy / pred);
            let w = 1.0 / (m.sigma_m as f64).powi(2);
            let r = m.range_m as f64 - pred;
            chi2 += w * r * r;
            a00 += w * jx * jx;
            a01 += w * jx * jy;
            a11 += w * jy * jy;
            b0 += w * jx * r;
            b1 += w * jy * r;
        }
        let det = a00 * a11 - a01 * a01;
        if det.abs() < 1e-12 {
            return None;
        }
        cov = [[a11 / det, -a01 / det], [-a01 / det, a00 / det]];
        let (sx, sy) = (
            cov[0][0] * b0 + cov[0][1] * b1,
            cov[1][0] * b0 + cov[1][1] * b1,
        );
        x += sx;
        y += sy;
        if !(x.is_finite() && y.is_finite()) {
            return None;
        }
        if sx * sx + sy * sy < 1e-8 {
            break;
        }
    }
    let dof = meas.len() as f64 - 2.0;
    let scale = if dof > 0.0 {
        (chi2 / dof).max(1.0).sqrt()
    } else {
        1.0
    };
    let sigma = ((cov[0][0] + cov[1][1]).max(0.0)).sqrt() * scale;
    Some((x as f32, y as f32, sigma as f32))
}

/// 可重現的亂數（xorshift64* + Box–Muller），讓模擬結果可測試。
pub struct Rng(u64);
impl Rng {
    pub fn new(seed: u64) -> Self {
        Self(seed.wrapping_mul(0x9E37_79B9_7F4A_7C15) | 1)
    }
    pub fn uniform(&mut self) -> f64 {
        self.0 ^= self.0 >> 12;
        self.0 ^= self.0 << 25;
        self.0 ^= self.0 >> 27;
        ((self.0.wrapping_mul(0x2545_F491_4F6C_DD1D) >> 11) as f64 + 0.5) / (1u64 << 53) as f64
    }
    pub fn normal(&mut self) -> f32 {
        let (u1, u2) = (self.uniform(), self.uniform());
        ((-2.0 * u1.ln()).sqrt() * (2.0 * std::f64::consts::PI * u2).cos()) as f32
    }
}

#[derive(Debug, Clone, Deserialize)]
pub struct SimRequest {
    /// 太空人的真實位置（模擬用；實際任務中未知）
    pub true_pos: [f32; 2],
    /// 上一個估計位置（沒有時用真實位置當初始）
    pub prev_estimate: Option<[f32; 2]>,
    pub prev_sigma: Option<f32>,
    /// 自上次估計以來的位移向量 [dx, dy]（公尺，來自步數／慣性量測）
    pub step_m: Option<[f32; 2]>,
    pub seed: Option<u64>,
    /// 失聯的信標 id（例如和基地斷線時關掉 hab）
    #[serde(default)]
    pub disabled: Vec<String>,
    /// 太空人在 EVA 途中自行布設的信標
    #[serde(default)]
    pub extra_beacons: Vec<Beacon>,
}

#[derive(Debug, Clone, Serialize)]
pub struct VisibleBeacon {
    pub id: String,
    pub kind: BeaconKind,
    pub x: f32,
    pub y: f32,
    /// 模擬的量測距離（含雜訊）
    pub range_m: f32,
}

#[derive(Debug, Clone, Serialize)]
pub struct SimResult {
    pub estimate: [f32; 2],
    pub sigma_m: f32,
    pub visible_beacons: Vec<VisibleBeacon>,
    /// "multilateration" 或 "dead_reckoning"
    pub mode: &'static str,
    /// 恆為 true：這是用 DEM 模擬的量測，不是真實感測器資料
    pub simulated: bool,
}

/// 模擬一次定位：判斷可見信標、產生含雜訊的測距，然後多邊定位或航位推算。
pub fn simulate(
    dem: &Grid<f32>,
    beacons: &[Beacon],
    nav: &NavParams,
    req: &SimRequest,
) -> SimResult {
    let mut rng = Rng::new(req.seed.unwrap_or(1));
    let (tx, ty) = (req.true_pos[0], req.true_pos[1]);
    let mut meas = vec![];
    let mut visible = vec![];
    let active = beacons
        .iter()
        .filter(|b| !req.disabled.iter().any(|d| d == &b.id))
        .chain(req.extra_beacons.iter());
    for b in active {
        if let Some(r) = visible_range(dem, b, nav, tx, ty) {
            let s = spec(nav, b.kind).sigma_m;
            let noisy = (r + s * rng.normal()).max(0.0);
            meas.push(RangeMeas {
                beacon: beacon_pos(dem, b, nav),
                range_m: noisy,
                sigma_m: s,
            });
            visible.push(VisibleBeacon {
                id: b.id.clone(),
                kind: b.kind,
                x: b.x,
                y: b.y,
                range_m: noisy,
            });
        }
    }
    let prev = req.prev_estimate.unwrap_or(req.true_pos);
    let prev_sigma = req.prev_sigma.unwrap_or(0.0);
    let step = req.step_m.unwrap_or([0.0, 0.0]);

    if meas.len() >= 3 {
        // 用「上一個估計 + 位移」當初始值，收斂快且避開鏡像解
        let init = (prev[0] + step[0], prev[1] + step[1]);
        // 幾何退化（信標擠在一起）時多點定位的誤差會比航位推算還大 → 不採用
        let dr_sigma =
            prev_sigma + nav.dr_growth_per_m * (step[0] * step[0] + step[1] * step[1]).sqrt();
        if let Some((x, y, s)) = multilaterate(dem, &meas, init, nav.suit_antenna_m)
            .filter(|&(_, _, s)| s.is_finite() && (s <= dr_sigma.max(30.0)))
        {
            return SimResult {
                estimate: [x, y],
                sigma_m: s,
                visible_beacons: visible,
                mode: "multilateration",
                simulated: true,
            };
        }
    }
    // 航位推算：上一個估計 + 位移（位移量測本身有 growth 比例的雜訊）
    let len = (step[0] * step[0] + step[1] * step[1]).sqrt();
    let odo_sigma = nav.dr_growth_per_m * len;
    let est = [
        prev[0] + step[0] + odo_sigma * rng.normal(),
        prev[1] + step[1] + odo_sigma * rng.normal(),
    ];
    SimResult {
        estimate: est,
        sigma_m: prev_sigma + odo_sigma,
        visible_beacons: visible,
        mode: "dead_reckoning",
        simulated: true,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn flat(w: usize, h: usize, cell: f32) -> Grid<f32> {
        Grid::new(w, h, cell, -4400.0)
    }

    fn beacon(id: &str, kind: BeaconKind, x: f32, y: f32) -> Beacon {
        Beacon {
            id: id.into(),
            kind,
            x,
            y,
            label: String::new(),
        }
    }

    #[test]
    fn los_flat_visible_and_wall_blocks() {
        let mut dem = flat(100, 20, 2.0);
        let nav = NavParams::default();
        let b = beacon("a", BeaconKind::Lora, 10.0, 20.0);
        assert!(visible_range(&dem, &b, &nav, 180.0, 20.0).is_some());
        // 中間立一道 20 m 高的牆（像陡崖）
        for j in 0..20 {
            dem.set(50, j, -4380.0);
        }
        assert!(visible_range(&dem, &b, &nav, 180.0, 20.0).is_none());
        // 同一側仍可見
        assert!(visible_range(&dem, &b, &nav, 60.0, 20.0).is_some());
    }

    #[test]
    fn out_of_range_invisible() {
        let dem = flat(200, 10, 2.0);
        let nav = NavParams::default();
        let u = beacon("u", BeaconKind::Uwb, 0.0, 10.0);
        assert!(visible_range(&dem, &u, &nav, 140.0, 10.0).is_some());
        assert!(visible_range(&dem, &u, &nav, 160.0, 10.0).is_none());
    }

    #[test]
    fn multilateration_exact_without_noise() {
        let dem = flat(200, 200, 2.0);
        let nav = NavParams::default();
        let truth = (210.0f32, 160.0f32);
        let bs = [(20.0, 30.0), (380.0, 40.0), (200.0, 390.0), (50.0, 300.0)];
        let sp = suit_pos(&dem, truth.0, truth.1, &nav);
        let meas: Vec<RangeMeas> = bs
            .iter()
            .map(|&(x, y)| {
                let bp = [x, y, terrain_z(&dem, x, y) + nav.beacon_antenna_m];
                RangeMeas {
                    beacon: bp,
                    range_m: dist3(bp, sp),
                    sigma_m: 2.0,
                }
            })
            .collect();
        let (x, y, s) = multilaterate(&dem, &meas, (100.0, 100.0), nav.suit_antenna_m).unwrap();
        assert!(
            ((x - truth.0).powi(2) + (y - truth.1).powi(2)).sqrt() < 0.1,
            "({x},{y})"
        );
        assert!(s > 0.0 && s < 5.0);
    }

    #[test]
    fn noisy_error_same_order_as_sigma() {
        let dem = flat(400, 400, 2.0);
        let nav = NavParams::default();
        let bs = vec![
            beacon("a", BeaconKind::Lora, 50.0, 50.0),
            beacon("b", BeaconKind::Lora, 750.0, 80.0),
            beacon("c", BeaconKind::Lora, 400.0, 760.0),
            beacon("d", BeaconKind::Lora, 90.0, 700.0),
        ];
        let truth = [420.0f32, 380.0];
        let mut sq = 0.0;
        let mut sig = 0.0;
        let n = 200;
        for seed in 0..n {
            let r = simulate(
                &dem,
                &bs,
                &nav,
                &SimRequest {
                    true_pos: truth,
                    prev_estimate: Some(truth),
                    prev_sigma: None,
                    step_m: None,
                    seed: Some(seed),
                    disabled: vec![],
                    extra_beacons: vec![],
                },
            );
            assert_eq!(r.mode, "multilateration");
            sq += (r.estimate[0] - truth[0]).powi(2) + (r.estimate[1] - truth[1]).powi(2);
            sig += r.sigma_m;
        }
        let rms = (sq / n as f32).sqrt();
        let mean_sigma = sig / n as f32;
        assert!(rms > 0.2 && rms < 6.0, "rms error {rms}");
        assert!(
            mean_sigma > 0.5 && mean_sigma < 8.0,
            "mean sigma {mean_sigma}"
        );
        assert!(
            rms < 3.0 * mean_sigma && mean_sigma < 3.0 * rms + 1.0,
            "rms {rms} vs sigma {mean_sigma}"
        );
    }

    #[test]
    fn falls_back_to_dead_reckoning_and_sigma_grows() {
        let dem = flat(200, 200, 2.0);
        let nav = NavParams::default();
        let bs = vec![beacon("a", BeaconKind::Lora, 10.0, 10.0)]; // 只有 1 個
        let r = simulate(
            &dem,
            &bs,
            &nav,
            &SimRequest {
                true_pos: [110.0, 100.0],
                prev_estimate: Some([100.0, 100.0]),
                prev_sigma: Some(1.0),
                step_m: Some([10.0, 0.0]),
                seed: Some(3),
                disabled: vec![],
                extra_beacons: vec![],
            },
        );
        assert_eq!(r.mode, "dead_reckoning");
        assert!((r.sigma_m - (1.0 + 0.02 * 10.0)).abs() < 1e-5);
        assert!((r.estimate[0] - 110.0).abs() < 2.0);
    }

    #[test]
    fn coverage_counts_visible_beacons() {
        let dem = flat(100, 100, 2.0);
        let nav = NavParams::default();
        let bs = vec![
            beacon("a", BeaconKind::Lora, 10.0, 10.0),
            beacon("u", BeaconKind::Uwb, 20.0, 20.0),
        ];
        let c = coverage(&dem, &bs, &nav, 4);
        assert_eq!(c.get(5, 5), 2.0); // 兩個都看得到
        assert_eq!(c.get(95, 95), 1.0); // UWB 超出 150 m
    }

    #[test]
    fn disabled_and_deployed_beacons() {
        let dem = flat(200, 200, 1.0);
        let nav = NavParams::default();
        let base = vec![
            beacon("a", BeaconKind::Uwb, 20.0, 20.0),
            beacon("b", BeaconKind::Uwb, 60.0, 20.0),
            beacon("c", BeaconKind::Uwb, 40.0, 60.0),
        ];
        let mut req = SimRequest {
            true_pos: [40.0, 35.0],
            prev_estimate: None,
            prev_sigma: None,
            step_m: None,
            seed: Some(3),
            disabled: vec![],
            extra_beacons: vec![],
        };
        assert_eq!(simulate(&dem, &base, &nav, &req).mode, "multilateration");
        // 斷了一個 → 只剩 2 個，改用航位推算
        req.disabled = vec!["a".into()];
        let r = simulate(&dem, &base, &nav, &req);
        assert_eq!(r.mode, "dead_reckoning");
        assert_eq!(r.visible_beacons.len(), 2);
        // 自己放一個新信標 → 又回到多點定位
        req.extra_beacons = vec![beacon("d1", BeaconKind::Uwb, 25.0, 45.0)];
        let r = simulate(&dem, &base, &nav, &req);
        assert_eq!(r.mode, "multilateration");
        assert!(r.visible_beacons.iter().any(|b| b.id == "d1"));
        // 新信標擠在已有信標旁邊（幾何退化）→ 不能讓誤差爆掉
        req.extra_beacons = vec![
            beacon("d1", BeaconKind::Uwb, 60.0, 20.1),
            beacon("d2", BeaconKind::Uwb, 60.1, 20.0),
        ];
        req.prev_sigma = Some(2.0);
        let r = simulate(&dem, &base, &nav, &req);
        assert!(r.sigma_m < 50.0, "sigma {}", r.sigma_m);
    }
}
